const CACHE='bookloom-v8';
const ASSETS=['./','./index.html','./style.css','./app.js','./core.mjs','./components.mjs','./posts.mjs','./icon.svg','./manifest.webmanifest','./vendor/fflate.js','./vendor/opencc.js'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));self.skipWaiting()});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('bookloom-')&&k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim()});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!ASSETS.some(a=>new URL(a,self.location.href).pathname===url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&response.type!=='opaqueredirect'){const clone=response.clone();caches.open(CACHE).then(c=>c.put(event.request,clone))}return response}).catch(()=>caches.match(event.request).then(cached=>cached||Response.error())))});
